/** System prompt — 工厂为【这一个】agent 亲自推理出来的。 */
const SYSTEM_PROMPT = `你是一个简历匹配准入规则校验专家。你的职责是在候选人进入简历匹配流程之前，执行公司通用规则和客户定制规则的双重校验，只有通过所有规则的候选人才能进入后续匹配环节。

执行步骤：
1. 接收 \`candidate_id\`、\`resume_id\` 和 \`job_requisition_id\`。
2. 必须调用 \`ontology.fetchActionRules\` 动态获取当前动作（ruleCheckForMatchResume）适用的所有规则，包括：
   - 公司通用准入规则（如黑名单检查、锁定状态检查）
   - 客户定制规则（如特定客户的离职冷静期、学历类型限制等）
   - 内推奖金资格动态角色冲突规则
3. 逐条对候选人信息进行规则校验：
   - 检查候选人是否在黑名单中
   - 检查候选人状态是否为"已锁定冲突"
   - 检查是否满足客户的离职冷静期要求
   - 检查学历类型是否符合客户要求
   - 检查是否存在内推角色冲突
4. 综合所有规则的校验结果：
   - 全部通过 → result="通过"，产出 MATCH_RULE_CHECK_PASSED
   - 任一规则未通过 → result="未通过"，reason 说明具体原因，产出 MATCH_RULE_CHECK_FAILED

注意：绝不要在 prompt 中硬编码任何具体规则内容，必须在运行时动态获取并执行。

【前置条件（运行前必须满足；不满足则 fail-close 发拦截/失败事件，不要继续）】
1. RESUME_PROCESSED事件已送达
2. 候选人(Candidate)记录已创建且candidate_id非空
3. 候选人简历(Resume)已完成结构化解析
4. 至少一个有效的招聘岗位(Job_Requisition)记录存在且hc_status不为"已关闭"`;

export const ruleCheckForMatchResumeAgent = defineAgent({
  id: "agents-gener-rule-check-for-match-resume",
  name: "RuleCheckForMatchResumeAgent",
  actor: ["Agent"],
  trigger: ["RESUME_PROCESSED"],
  emit: ["MATCH_RULE_CHECK_PASSED","MATCH_RULE_CHECK_FAILED"],
  tools: ["ontology.fetchActionRules"],
  systemPrompt: SYSTEM_PROMPT,
  async handler(input, ctx) {
      // 调用工具 ontology.fetchActionRules
      // const fetchActionRulesResult = await ctx.tools.run("ontology.fetchActionRules", input);
      // 用本 agent 专属 system prompt 推理(决策核心)
      const decision = await ctx.reason(SYSTEM_PROMPT, input);
      // 决策分支（条件见 SYSTEM_PROMPT / decisionLogic）
      if (decision.pass) {
        await ctx.emit("MATCH_RULE_CHECK_PASSED", { ...input, ...decision });
      } else {
        await ctx.emit("MATCH_RULE_CHECK_FAILED", { ...input, ...decision });
      }
      return { ok: true };
  },
});

// 对已经通过简历匹配规则检查的候选人简 — 由 Agent 工厂从本体动作 `matchResume`(Agents-generation)生成。
// trigger: MATCH_RULE_CHECK_PASSED → emit: MATCH_PASSED_NEED_INTERVIEW | MATCH_PASSED_NO_INTERVIEW | MATCH_FAILED
// 参考脚手架：运行时按 workflow manifest 的 action[] 声明式调度执行（systemPrompt + 工具），
// 【不直接运行这段 .ts 代码】——它是可读/可改的 agent 定义参考。真·CodeAct 执行路径用 codeExecuted 开关（默认关）。

/** Input/Output schema — 依据本体 DataObjects 定义。 */
interface MatchResumeAgentInput {
  candidate_id: string; // 待匹配的候选人唯一编号 (源: Candidate.candidate_id)
  resume_id: string; // 待匹配的候选人简历唯一编号 (源: Resume.resume_id)
  job_requisition_id: string; // 候选人待匹配的招聘岗位编号 (源: Job_Requisition.job_requisition_id)
